before.style.css:
        body {
            font-family: Arial, sans-serif;
            background-color: #f4f4f9;
            color: #333;
            margin: 0;
            padding: 0;
            line-height: 1.6;
            transition: background-color 0.3s, color 0.3s;
        }
        .container {
            width: 80%;
            margin: 0 auto;
            padding: 20px;
        }
        .header {
            background-color: #007bff;
            color: #fff;
            padding: 10px 0;
            text-align: center;
        }
        .header button {
            background-color: #fff;
            color: #007bff;
            border: none;
            padding: 10px 20px;
            cursor: pointer;
            border-radius: 5px;
            text-decoration: none;
            margin-top: 10px;
        }
        .header button:hover {
            background-color: #0056b3;
            color: #fff;
        }
        .section {
            margin-bottom: 20px;
        }
        .section-title {
            background-color: #333;
            color: #fff;
            padding: 10px;
            text-align: center;
        }
        .content {
            padding: 10px;
        }

        /* Dark mode styles */
        body.dark-mode {
            background-color: #333;
            color: #f4f4f9;
        }
        .header.dark-mode {
            background-color: #333;
            color: #f4f4f9;
        }
        .header.dark-mode button {
            background-color: #f4f4f9;
            color: #333;
        }
        .header.dark-mode button:hover {
            background-color: #0056b3;
            color: #f4f4f9;
        }
        .section-title.dark-mode {
            background-color: #f4f4f9;
            color: #333;
        }

